@model (string title, string imageUrl)

<div class="hero-block mb-8">
    @if (!string.IsNullOrEmpty(Model.imageUrl))
    {
        <img src="@Model.imageUrl" alt="@Model.title" class="w-full h-96 object-cover rounded-lg mb-4" />
    }
    <h2 class="text-3xl font-bold">@Model.title</h2>
</div>

